00) NULL,\n33:     level VARCHAR(50) NULL\n34: );\n35: \n36: -- 3. جدول الدرجات\n37: CREATE TAB\n<truncated 2824 bytes>\nموقع فوراً)\n110: -- ============================================================\n111: \n112: -- المستخدمين\n113: INSERT INTO users (full_name, email, password, role, permission_level, student_id, department, level, payment_status) VALUES\n114: ('مدير الكلية', 'admin@college.com', MD5('123456'), 'staff', 3, NULL, NULL, NULL, 'paid'),\n115: ('موظف الكلية', 'staff@college.com', MD5('123456'), 'staff', 2, NULL, NULL, NULL, 'paid'),\n116: ('أحمد محمد', 'ahmed@student.com', MD5('123456'), 'student', 1, '2024001', 'علوم الحاسوب', 'المستوى الأول', 'unpaid'),\n117: ('سارة علي', 'sara@student.com', MD5('123456'), 'student', 1, '2024002', 'علوم الحاسوب', 'المستوى الأول', 'paid');\n118: \n119: -- المواد الدراسية\n120: INSERT INTO subjects (subject_name, subject_code, department, level) VALUES\n121: ('قواعد البيانات', 'DB101', 'علوم الحاسوب', 'المستوى الأول'),\n122: ('برمجة الويب', 'WEB201', 'علوم الحاسوب', 'المستوى الثاني'),\n123: ('الذكاء الاصطناعي', 'AI301', 'علوم الحاسوب', 'المستوى الثالث'),\n124: ('تشريح', 'ANAT101', 'العلوم الطبية', 'المستوى الأول'),\n125: ('صيدلة سريرية', 'CLP101', 'صيدلة', 'المستوى الثاني');\n126: \n127: -- الإعلانات\n128: INSERT INTO announcements (title, content, created_by) VALUES\n129: ('📢 بدء التسجيل للفصل الدراسي الجديد', 'يسر عمادة الكلية الإعلان عن بدء التسجيل للفصل الدراسي الأول للعام الجامعي 2026/2027 اعتباراً من 1 سبتمبر 2026.', 1),\n130: ('🎓 تخفيضات للطلاب المتفوقين', 'تعلن الكلية عن تخفيض 30% من الرسوم الدراسية للطلاب الحاصلين على معدل 90% فأعلى.', 1);\nThe above content shows the entire, complete file contents of the requested file.\n","truncated_fields":["content"]}
